247	async function tsCompile(compilerOptionsOverride, srcPathList) {
248	    assert(
249	        compilerOptionsOverride
250	        && compilerOptionsOverride.module
251	        && compilerOptionsOverride.rootDir
252	        && compilerOptionsOverride.outDir
253	    );
254	
255	    let compilerOptions = {
256	        ...tsConfig.compilerOptions,
257	        ...compilerOptionsOverride,
258	        sourceMap: false
259	    };
260	
261	    runTsCompile(ts, compilerOptions, srcPathList);
262	}
