288	async function transformLibFiles(rooltFolder, replacement) {
289	    const files = await readFilePaths({
290	        patterns: ['**/*.js', '**/*.d.ts'],
291	        cwd: rooltFolder
292	    });
293	    // Simple regex replacement
294	    // TODO More robust way?
295	    for (let fileName of files) {
296	        let code = fs.readFileSync(fileName, 'utf-8');
297	        code = singleTransformImport(code, replacement);
298	        // For lower ts version, not use import type
299	        // TODO Use https://github.com/sandersn/downlevel-dts ?
300	        // if (fileName.endsWith('.d.ts')) {
301	        //     code = singleTransformImportType(code);
302	        // }
303	        fs.writeFileSync(fileName, code, 'utf-8');
304	    }
305	}
