346	async function transformCode({filesGlobby, preamble, transformDEV}) {
347	
348	    let filePaths = await readFilePaths(filesGlobby);
349	
350	    filePaths.map(filePath => {
351	        let code = fs.readFileSync(filePath, 'utf8');
352	
353	        if (transformDEV) {
354	            let result = transformDEVUtil.transform(code, false);
355	            code = result.code;
356	        }
357	
358	        code = autoGeneratedFileAlert + code;
359	
360	        if (preamble) {
361	            code = preamble + code;
362	        }
363	
364	        fs.writeFileSync(filePath, code, 'utf8');
365	    });
366	}
