368	async function readFilePaths({patterns, cwd}) {
369	    assert(patterns && cwd);
370	    return (
371	        await globby(patterns, {cwd})
372	    ).map(
373	        srcPath => nodePath.resolve(cwd, srcPath)
374	    );
375	}
