438	function readTSConfig() {
439	    // tsconfig.json may have comment string, which is invalid if
440	    // using `require('tsconfig.json'). So we use a loose parser.
441	    let filePath = nodePath.resolve(ecDir, 'tsconfig.json');
442	    const tsConfigText = fs.readFileSync(filePath, {encoding: 'utf8'});
443	    return (new Function(`return ( ${tsConfigText} )`))();
444	}
